messages.content:
{
  "bucket": "medianas",
  "temas": [
    {
      "tema": "Ritmo lento ou arrastado",
      "mencoes_aproximadas": 14,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Alguns espectadores acharam o filme cansativo e com ritmo lento, mencionando que a narrativa em um único ambiente e com diálogos constantes tornou a experiência monótona para eles."
    },
    {
      "tema": "Final previsível",
      "mencoes_aproximadas": 11,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Vários comentários indicam que o desfecho era previsível desde o início, o que diminuiu a surpresa e o impacto emocional para parte do público."
    },
    {
      "tema": "Expectativa vs. realidade (superestimado)",
      "mencoes_aproximadas": 9,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas pessoas sentiram que o filme não correspondeu à fama de obra-prima, considerando-o superestimado ou menos impactante do que esperavam."
    },
    {
      "tema": "Atuações e diálogos",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Há elogios às atuações e à qualidade dos diálogos, com destaque para a construção dos personagens e a tensão gerada pelas discussões."
    },
    {
      "tema": "Roteiro e argumentação",
      "mencoes_aproximadas": 7,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Alguns espectadores criticaram a lógica dos argumentos e a facilidade com que os jurados mudam de opinião, enquanto outros elogiaram a construção dos debates."
    },
    {
      "tema": "Fotografia e direção",
      "mencoes_aproximadas": 5,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Comentários mencionam a eficácia da fotografia em preto e branco e os movimentos de câmera que intensificam a claustrofobia e a tensão do ambiente único."
    }
  ],
  "observacao_geral": "As reviews medianas destacam que, embora o filme tenha uma premissa interessante e boas atuações, muitos o consideraram lento, previsível e aquém das expectativas criadas por sua reputação. Este grupo também aponta que a argumentação e a reviravolta emocional não convenceram totalmente."
}

{
  "bucket": "negativas",
  "temas": [
    {
      "tema": "Ritmo lento e tédio",
      "mencoes_aproximadas": 27,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Muitas reviews descrevem o filme como arrastado e monótono, com relatos de cochilos durante a exibição e sensação de que os noventa minutos pareceram uma eternidade."
    },
    {
      "tema": "Ambientação única e falta de dinamismo visual",
      "mencoes_aproximadas": 13,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O fato de toda a ação se passar em um único cômodo é apontado como limitante, com alguns espectadores sentindo falta de variação de cenários e de recursos visuais que mantenham o interesse."
    },
    {
      "tema": "Diálogo excessivo e repetitivo",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As reviews destacam que o filme se sustenta apenas em conversa constante, com argumentos que se repetem e discussões que giram em círculos sem avanço significativo."
    },
    {
      "tema": "Previsibilidade e roteiro raso",
      "mencoes_aproximadas": 9,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Vários espectadores afirmam que o desfecho é óbvio desde o início e que as reflexões propostas soam superficiais ou pouco originais."
    },
    {
      "tema": "Preto e branco como incômodo",
      "mencoes_aproximadas": 7,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A fotografia em preto e branco é citada como um obstáculo, com alguns relatando desconforto visual ou dificuldade de imersão por causa disso."
    },
    {
      "tema": "Personagens e atuações criticados",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas reviews mencionam falta de desenvolvimento dos personagens e atuações consideradas exageradas ou pouco convincentes."
    }
  ],
  "observacao_geral": "Este grupo de reviews negativas concentra suas críticas no ritmo arrastado, na ambientação estática e no excesso de diálogo, além de apontar previsibilidade e falta de impacto emocional. Apesar disso, algumas reviews reconhecem qualidades técnicas e de atuação, mas afirmam que isso não foi suficiente para tornar a experiência agradável para elas."
}

{
  "bucket": "positivas",
  "temas": [
    {
      "tema": "Roteiro e construção narrativa",
      "mencoes_aproximadas": 22,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As reviews elogiam a escrita precisa e a forma como o roteiro sustenta o interesse do início ao fim, construindo tensão apenas com diálogo."
    },
    {
      "tema": "Atuações do elenco",
      "mencoes_aproximadas": 18,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Grande parte das críticas destaca a qualidade das atuações individuais e do elenco em conjunto, com menções frequentes a Henry Fonda e Lee J. Cobb."
    },
    {
      "tema": "Tensão em espaço único",
      "mencoes_aproximadas": 16,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O grupo valoriza como o filme cria claustrofobia e tensão sem sair quase nunca do mesmo ambiente, usando a limitação espacial a favor da narrativa."
    },
    {
      "tema": "Temas de justiça e preconceito",
      "mencoes_aproximadas": 14,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Várias reviews ressaltam como o filme discute justiça, dúvida razoável, pressão de grupo e preconceito de forma humanista e ainda relevante."
    },
    {
      "tema": "Fotografia e encenação",
      "mencoes_aproximadas": 11,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A fotografia em preto e branco, os enquadramentos fechados e a direção de cena são citados como elementos que amplificam a tensão psicológica."
    },
    {
      "tema": "Ritmo e diálogo",
      "mencoes_aproximadas": 10,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As críticas mencionam que o filme mantém o ritmo ágil apesar de ser centrado em conversas, prendendo a atenção do espectador durante toda a projeção."
    }
  ],
  "observacao_geral": "As reviews positivas apontam para um grande apreço pela condução do roteiro, pelas atuações e pela capacidade de gerar tensão em um único ambiente, além de destacarem a discussão sobre justiça e preconceito como um dos pontos mais fortes da obra. Este grupo também valoriza a fotografia, a encenação e o ritmo como fatores que tornam a experiência envolvente e duradoura."
}

{
  "bucket": "medianas",
  "temas": [
    {
      "tema": "Dificuldade de conexão emocional com os personagens",
      "mencoes_aproximadas": 14,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Várias reviews medianas relatam que, apesar da qualidade técnica, não conseguiram se envolver emocionalmente com os soldados, achando-os pouco desenvolvidos ou genéricos, o que prejudicou o impacto da história."
    },
    {
      "tema": "Ritmo lento e duração excessiva",
      "mencoes_aproximadas": 10,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas pessoas deste grupo consideraram o filme arrastado, com sequências longas que não acrescentam, levando à desconexão ou tédio, especialmente na primeira metade."
    },
    {
      "tema": "Elogio à fotografia e aspectos técnicos",
      "mencoes_aproximadas": 9,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As reviews medianas frequentemente elogiam a fotografia, a trilha sonora e a recriação visual da guerra, descrevendo-as como impressionantes e imersivas, mesmo quando a narrativa não convence."
    },
    {
      "tema": "Retrato brutal e realista da guerra",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Este grupo reconhece que o filme retrata de forma crua e realista os horrores das trincheiras, a violência e o sofrimento dos soldados, transmitindo a brutalidade do conflito."
    },
    {
      "tema": "Comparações desfavoráveis com o livro ou versões anteriores",
      "mencoes_aproximadas": 7,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Diversas reviews medianas apontam que a adaptação deixa de fora cenas e críticas essenciais do romance original, como o retorno do protagonista à vida civil, e que outras versões transmitiram melhor a mensagem antiguerra."
    },
    {
      "tema": "Crítica à subtrama política e ao excesso de didatismo",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas reviews medianas criticam a inclusão da trama política com generais caricatos, que soa artificial e quebra o ritmo, além de considerarem a mensagem antiguerra óbvia ou pouco sutil."
    }
  ],
  "observacao_geral": "As reviews desta faixa mediana (2,5–3 estrelas) reconhecem a qualidade técnica e o retrato brutal da guerra, mas apontam com frequência a falta de conexão emocional com os personagens e problemas de ritmo; muitas também comparam a obra desfavoravelmente com o livro ou versões anteriores. Apesar das ressalvas, várias consideram o filme eficaz em transmitir os horrores do conflito, mesmo sem gerar grande impacto pessoal."
}

{
  "bucket": "positivas",
  "temas": [
    {
      "tema": "Representação crua e realista da guerra",
      "mencoes_aproximadas": 32,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As reviews destacam que o filme retrata a guerra de forma crua e realista, mostrando o sofrimento, a brutalidade e a falta de sentido do conflito, sem romantizá-lo."
    },
    {
      "tema": "Fotografia e aspectos técnicos",
      "mencoes_aproximadas": 18,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A fotografia é frequentemente elogiada como bela e impactante, contribuindo para a imersão na atmosfera do filme, assim como a trilha sonora e os efeitos visuais."
    },
    {
      "tema": "Atuações e personagens",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As atuações, especialmente a do protagonista, são bastante elogiadas, com destaque para a transformação do personagem ao longo da narrativa."
    },
    {
      "tema": "Crítica à guerra e aos líderes",
      "mencoes_aproximadas": 10,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O filme é visto como uma forte crítica à guerra e àqueles que a promovem, contrastando o sofrimento dos soldados com a indiferença dos líderes."
    },
    {
      "tema": "Adaptação do livro",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas reviews comparam o filme ao livro, notando que a adaptação é boa, mas deixa de fora aspectos considerados importantes por leitores da obra original."
    },
    {
      "tema": "Impacto emocional",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Muitos espectadores relatam que o filme é emocionalmente pesado, triste e perturbador, deixando uma impressão duradoura."
    }
  ],
  "observacao_geral": "As reviews positivas destacam a representação realista e crua da guerra, elogiando a fotografia e as atuações, e frequentemente mencionam o impacto emocional profundo do filme. A crítica à guerra e aos líderes também é um ponto recorrente, assim como comparações com o livro original."
}

{
  "bucket": "medianas",
  "temas": [
    {
      "tema": "Ritmo lento e arrastado",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Várias reviews medianas reclamam que o filme demora a engrenar e que a primeira metade é entediante, com alguns dizendo que quase desistiram antes de se envolver."
    },
    {
      "tema": "Roteiro confuso e execução frustrante",
      "mencoes_aproximadas": 11,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Este grupo aponta que a premissa é interessante, mas a execução e o desenvolvimento da história soam confusos, com ideias mal aproveitadas e um desfecho pouco satisfatório."
    },
    {
      "tema": "Fotografia e trilha sonora elogiadas",
      "mencoes_aproximadas": 10,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As reviews medianas costumam elogiar a beleza visual, o design dos alienígenas e o som atmosférico, considerando esses os melhores aspectos do filme."
    },
    {
      "tema": "Crítica à propaganda estadunidense e à geopolítica",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Algumas reviews medianas criticam o retrato estereotipado de outras nações e a visão de que os Estados Unidos seriam os únicos racionais e pacíficos, o que incomoda durante a exibição."
    },
    {
      "tema": "Clichês e falta de originalidade",
      "mencoes_aproximadas": 7,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Há quem diga que o filme recorre a clichês do gênero, como traumas familiares e personagens genéricos, o que faz a obra parecer derivada de outras ficções científicas."
    },
    {
      "tema": "Atuações e personagens questionados",
      "mencoes_aproximadas": 5,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Parte deste grupo considera as atuações boas, mas acha a protagonista sem personalidade ou os personagens pouco cativantes."
    }
  ],
  "observacao_geral": "As reviews medianas apontam para uma experiência mista: embora a fotografia, o som e a premissa sejam frequentemente elogiados, o ritmo lento, o roteiro confuso e a execução frustrante decepcionam boa parte deste grupo. Críticas à propaganda estadunidense e aos clichês também aparecem com força."
}

{
  "bucket": "negativas",
  "temas": [
    {
      "tema": "Ritmo lento e entediante",
      "mencoes_aproximadas": 22,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Várias reviews descrevem o filme como excessivamente lento, com longos períodos em que nada parece acontecer, tornando a experiência arrastada e difícil de acompanhar."
    },
    {
      "tema": "Personagens pouco desenvolvidos e difíceis de se conectar",
      "mencoes_aproximadas": 14,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Alguns espectadores afirmam que não conseguiram se importar com os personagens, considerando-os rasos e sem profundidade emocional, o que prejudicou o envolvimento com a história."
    },
    {
      "tema": "Roteiro confuso e com furos",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O roteiro é criticado por deixar pontas soltas, apresentar explicações insuficientes e desenvolvimento apressado, com eventos que surgem sem preparação adequada."
    },
    {
      "tema": "Twist final decepcionante ou previsível",
      "mencoes_aproximadas": 9,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A reviravolta do final é apontada como óbvia, mal construída ou pouco satisfatória, soando como uma solução fácil em vez de uma conclusão merecida."
    },
    {
      "tema": "Tom excessivamente sério e melodramático",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O filme é visto como pretensioso e artificialmente emotivo, com um estilo que se leva a sério demais e diálogos que soam falsos ou piegas."
    },
    {
      "tema": "Cinematografia e efeitos visuais elogiados, mas insuficientes",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Apesar de reconhecerem a qualidade estética e os efeitos, muitos consideram que o visual bonito não compensa as falhas de história e ritmo."
    }
  ],
  "observacao_geral": "As reviews negativas analisadas destacam principalmente o ritmo lento e entediante, a dificuldade de conexão com os personagens e problemas no roteiro. Apesar de elogios pontuais à cinematografia, este grupo considerou a experiência arrastada e pouco envolvente."
}

{
  "bucket": "negativas",
  "temas": [
    {
      "tema": "Roteiro preguiçoso e incoerente",
      "mencoes_aproximadas": 15,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O roteiro parece uma colcha de retalhos, com diálogos fracos e situações forçadas apenas para mover a trama."
    },
    {
      "tema": "Favoritismo e nostalgia forçada",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "O filme apela descaradamente à nostalgia, relembrando cenas e personagens do passado em vez de criar algo novo."
    },
    {
      "tema": "Problemas de ritmo e duração",
      "mencoes_aproximadas": 11,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A duração é excessiva e o ritmo é arrastado, especialmente na primeira metade, tornando a experiência entediante."
    },
    {
      "tema": "Desenvolvimento de personagens decepcionante",
      "mencoes_aproximadas": 10,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Personagens como Thor e Hulk são reduzidos a piadas, e suas jornadas emocionais são tratadas de forma superficial."
    },
    {
      "tema": "Tratamento injusto de personagens femininas",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A morte de uma personagem feminina central é usada apenas como motivação para o sofrimento masculino, e sua importância é diminuída."
    },
    {
      "tema": "Efeitos visuais e estética comprometidos",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "A direção de arte e o CGI são criticados por serem visualmente feios e pouco inspirados, especialmente na batalha final."
    }
  ],
  "observacao_geral": "As críticas negativas apontam para uma produção que falha em honrar sua própria mitologia, priorizando fan service e momentos de hype em detrimento de uma narrativa coesa e personagens bem desenvolvidos. Ainda assim, reconhecem que o filme pode agradar aos fãs mais dedicados da franquia, embora isso não justifique seus defeitos estruturais."
}

{
  "bucket": "positivas",
  "temas": [
    {
      "tema": "Carga emocional e despedidas",
      "mencoes_aproximadas": 25,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Muitas pessoas mencionaram que choraram em várias cenas, especialmente nas despedidas de personagens queridos, e que a parte final do filme é extremamente emocionante e marcante, trazendo um sentimento de encerramento para uma era."
    },
    {
      "tema": "Batalha final épica e fan service",
      "mencoes_aproximadas": 18,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Vários espectadores destacaram a sequência final de batalha como a melhor parte do filme, elogiando a reunião dos heróis e a sensação de recompensa para os fãs de longa data, descrevendo-a como um espetáculo visual e emocionante."
    },
    {
      "tema": "Viagem no tempo e lógica interna",
      "mencoes_aproximadas": 7,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Alguns comentários mencionaram que a viagem no tempo é um recurso ousado e com inconsistências, mas que funciona bem para revisitar momentos icônicos da franquia e aprofundar o drama, apesar de algumas decisões questionáveis na trama."
    },
    {
      "tema": "Performance do elenco e momentos dos personagens",
      "mencoes_aproximadas": 6,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Houve elogios às atuações, especialmente de Robert Downey Jr., e a momentos específicos como a redenção do Capitão América e o sacrifício da Viúva Negra, que foram considerados fortes e bem executados."
    },
    {
      "tema": "Comparação com Infinity War",
      "mencoes_aproximadas": 5,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Parte dos fãs debateram se este filme é superior ou inferior ao anterior, com alguns preferindo a abordagem mais focada nos heróis e outros achando que a narrativa do filme anterior era mais coesa, mas muitos concordam que ambos são marcos do cinema."
    },
    {
      "tema": "Ritmo e duração",
      "mencoes_aproximadas": 4,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Alguns comentários apontaram que o filme tem um ritmo irregular, com uma primeira metade mais lenta, mas que a conclusão compensa, e que as três horas de duração parecem passar rápido devido ao envolvimento emocional."
    }
  ],
  "observacao_geral": "As reviews positivas destacam o enorme apelo emocional e o impacto cultural do filme, considerando-o um encerramento épico e nostálgico da saga. Apesar de algumas ressalvas pontuais sobre ritmo e lógica da viagem no tempo, o grupo valoriza a experiência coletiva e os momentos de fan service como recompensa para os fãs."
}

{
  "bucket": "negativas",
  "temas": [
    {
      "tema": "Discurso feminista forçado e sem sutileza",
      "mencoes_aproximadas": 16,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "As críticas apontam que o filme martela sua mensagem feminista de forma exagerada, sem deixar espaço para interpretação, tratando o público como se não fosse capaz de entender subtextos."
    },
    {
      "tema": "Roteiro confuso e sem direção clara",
      "mencoes_aproximadas": 12,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Muitos espectadores reclamam que o filme não parece saber o que quer transmitir, misturando tantas ideias que o resultado final fica confuso e sem um propósito definido."
    },
    {
      "tema": "Ritmo arrastado e tédio",
      "mencoes_aproximadas": 8,
      "n_reviews_analisadas": 40,
      "exemplo_parafraseado": "Várias pessoas relatam que se entediaram em alguns momentos, especialmente na parte do mundo real, chegando a abandonar a sala ou a pausar o filme."
    },
    {
      "tema": "Publicidade e comercialismo excessivo",
